few_shot_examples.query:
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?place ?fire ?property ?propertyLabel ?value
WHERE {
  ?fire a/rdfs:subClassOf* kwg-ont:Fire .

  OPTIONAL { ?fire kwg-ont:spatialRelation ?place . }
  OPTIONAL { ?fire geo:hasGeometry ?geometry . }

  ?obs sosa:hasFeatureOfInterest ?fire ;
       sosa:observedProperty ?property ;
       sosa:hasSimpleResult ?value .

  OPTIONAL { ?property rdfs:label ?propertyLabel . }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?fireType ?superType ?property ?value
WHERE {
  ?fireType rdfs:subClassOf* kwg-ont:Fire .
  OPTIONAL { ?fireType rdfs:subClassOf ?superType . }
  OPTIONAL { ?fireType ?property ?value . }
}
ORDER BY ?fireType ?property

PREFIX kwg-ont: <http://example.org/kwg-ont/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?place ?hazard ?property ?value
WHERE {
  ?hazard a kwg-ont:Hazard .
  ?hazard kwg-ont:spatialRelation ?place .
  ?obs sosa:hasFeatureOfInterest ?hazard ;
       sosa:observedProperty ?property ;
       sosa:hasSimpleResult ?value .
}

PREFIX kwg-ont: <http://example.org/kwg-ont/>
PREFIX kwgr: <http://example.org/kwgr/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?place ?damage ?value ?time ?start ?end
WHERE {
  ?hazard a kwg-ont:NOAAFlood .
  ?hazard kwg-ont:spatialRelation ?place .

  ?obs a kwg-ont:ImpactObservation ;
       sosa:hasFeatureOfInterest ?hazard ;
       sosa:observedProperty ?damage ;
       sosa:hasSimpleResult ?value ;
       sosa:phenomenonTime ?time .

  OPTIONAL {
    ?time time:hasBeginning ?start .
    ?time time:hasEnd ?end .
  }
}

PREFIX kwg-ont: <http://example.org/kwg-ont/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard ?place ?damageType ?damageValue ?time
WHERE {

  # Hazard (landslide-related)
  ?hazard a ?hazardType .
  ?hazardType rdfs:subClassOf* kwg-ont:NOAAHazardEvent .
  FILTER(CONTAINS(LCASE(STR(?hazardType)), "landslide")) .

  # Spatial relation to place
  ?hazard kwg-ont:spatialRelation ?place .

  # Impact / damage observation
  ?obs a kwg-ont:ImpactObservation ;
       sosa:hasFeatureOfInterest ?hazard ;
       sosa:observedProperty ?damageType ;
       sosa:hasSimpleResult ?damageValue ;
       sosa:phenomenonTime ?time .
}

